fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x0c0c0c);
    let base: i32 = h - 60;
    let gw: i32 = (w - 40) / 5;
    let bw: i32 = (gw - 16) / 2;
    let mut i: i32 = 0;
    while i < 5 {
        let this: i32 = 20 + (i * i * 7) % 60;
        let last: i32 = 15 + (i * 23) % 60;
        let gx: i32 = 20 + i * gw;
        host::display::fill_rect(gx, base - this * 3, bw, this * 3, 0x40c0ff);
        host::display::fill_rect(gx + bw + 4, base - last * 3, bw, last * 3, 0x606870);
        host::display::draw_number(gx + bw / 2, base + 8, i + 1, 0x808080, 2);
        i = i + 1;
    }
    host::display::draw_line(16, base, w - 16, base, 0xc0c0c0);
    host::display::fill_rect(20, 12, 10, 10, 0x40c0ff);
    host::display::draw_string(36, 12, "THIS", 0xc0c0c0, 1);
    host::display::fill_rect(90, 12, 10, 10, 0x606870);
    host::display::draw_string(106, 12, "LAST", 0xc0c0c0, 1);
    host::display::present();
}
